<?php require_once '../includes/config.php'; require_permission('inventory');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('UPDATE products SET stock=? WHERE id=?')->execute([(int)$_POST['stock'],(int)$_POST['id']]);flash('success','Stock updated.');redirect('inventory.php');}$rows=$pdo->query('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.stock ASC')->fetchAll();$title='Inventory';require '../includes/header.php';?><h1 class="section-title">Inventory Management</h1><div class="panel overflow-hidden"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Product</th><th>Category</th><th>Stock</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['category_name'])?></td><td><span class="badge <?=$r['stock']<5?'bg-danger':'bg-success'?>"><?=$r['stock']?></span></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input class="form-control form-control-sm" style="max-width:110px" type="number" name="stock" min="0" value="<?=$r['stock']?>"><button class="btn btn-sm btn-purple">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require '../includes/footer.php'; ?>